+    private StoreContext prepareStore(File folder, File index, boolean creationAllowed,
+            IntegrityMode configuredIntegrityMode, StoreState configuredState) {
+        Path folderPath = folder.toPath().toAbsolutePath().normalize();
+        Path indexPath = index.toPath().toAbsolutePath().normalize();
