+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        ensureInitialized();
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (state.lock) {
+            String description = rule.getDescription();
+            String existingFileName = storedRules.getProperty(description);
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                if (existingFileName != null) {
+                    forgetRule(description, existingFileName);
+                }
+                return;
+            }
+
+            String fileName = existingFileName != null
+                    ? existingFileName
+                    : fileNameOrThrow(description, StoreUpdateFailedException.class);
+            Path target = validateSaveTarget(description, fileName, existingFileName != null);
+            Path fileToWrite = existingTarget(target);
+            boolean targetWasAbsent = !Files.exists(fileToWrite, LinkOption.NOFOLLOW_LINKS);
+            writeAtomically(fileToWrite, violations);
+
+            if (existingFileName == null) {
+                storedRules.put(description, fileName);
+                try {
+                    storedRules.syncFileSystem();
+                } catch (RuntimeException e) {
+                    if (targetWasAbsent) {
+                        deleteQuietly(fileToWrite);
+                    }
+                    storedRules.remove(description);
+                    throw e;
+                }
+            }
+        }
+    }
+
+    private Path validateSaveTarget(String description, String fileName, boolean existingEntry) {
+        Path target = context.folderPath.resolve(fileName).normalize();
+        if (!isDirectPath(target, context.folderPath) || target.equals(context.indexPath)
+                || target.equals(context.indexRealPath)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot store rule '%s' in unsafe violation file '%s'", description, fileName));
+        }
+        boolean targetExists = Files.exists(target, LinkOption.NOFOLLOW_LINKS);
+        if (!existingEntry && storedRules.containsValue(fileName)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot store rule '%s': violation file '%s' is already recorded by another rule",
+                    description, fileName));
+        }
+        if (!existingEntry && targetExists) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot store rule '%s': violation file '%s' already exists", description, fileName));
+        }
+        if (targetExists && !Files.isRegularFile(target)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot store rule '%s': violation path '%s' is not a regular file", description, fileName));
+        }
+        if (targetExists) {
+            try {
+                Path realPath = target.toRealPath();
+                if (!realPath.getParent().equals(context.folderRealPath)
+                        || realPath.equals(context.indexRealPath)) {
+                    throw new StoreUpdateFailedException(String.format(
+                            "Cannot store rule '%s' in unsafe violation file '%s'", description, fileName));
+                }
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+        return target;
+    }
+
+    private Path existingTarget(Path target) {
+        if (!Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
+            return target;
+        }
+        try {
+            return target.toRealPath();
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private void forgetRule(String description, String fileName) {
+        ResolvedFile file = resolveFile(fileName);
+        if (file.broken) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot forget rule '%s': its violation file is not a regular file directly in the store folder",
+                    description));
+        }
+        if (!file.actualPath.equals(context.indexRealPath)) {
+            boolean shared = isSharedByAnotherRule(description, file);
+            try {
+                if (!shared) {
+                    Files.deleteIfExists(file.actualPath);
+                    if (!file.lexicalPath.equals(file.actualPath)) {
+                        Files.deleteIfExists(file.lexicalPath);
+                    }
+                } else if (!file.lexicalPath.equals(file.actualPath)) {
+                    Files.deleteIfExists(file.lexicalPath);
+                }
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+        storedRules.remove(description);
+        storedRules.syncFileSystem();
+    }
+
+    private boolean isSharedByAnotherRule(String description, ResolvedFile file) {
+        for (String otherDescription : storedRules.stringPropertyNames()) {
+            if (!otherDescription.equals(ensureUnixLineBreaks(description))) {
+                String otherName = storedRules.getProperty(otherDescription);
+                ResolvedFile other = resolveFile(otherName);
+                if (!other.broken && file.identity.equals(other.identity)) {
+                    return true;
+                }
+                if (otherName.equals(file.lexicalPath.getFileName().toString())) {
+                    return true;
+                }
+            }
+        }
+        return false;
+    }
+
+    private void writeAtomically(Path target, List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        Path temporary = null;
+        try {
+            temporary = Files.createTempFile(context.folderPath, ".violation-", ".tmp");
+            Files.write(temporary, builder.toString().getBytes(UTF_8), StandardOpenOption.TRUNCATE_EXISTING);
+            moveReplacing(temporary, target);
+        } catch (IOException e) {
+            if (temporary != null) {
+                deleteQuietly(temporary);
+            }
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private void moveReplacing(Path source, Path target) throws IOException {
+        try {
+            Files.move(source, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
+        } catch (AtomicMoveNotSupportedException e) {
+            Files.move(source, target, StandardCopyOption.REPLACE_EXISTING);
+        }
+    }
+
+    private void ensureInitialized() {
+        if (storedRules == null) {
+            throw new IllegalStateException("TextFileBasedViolationStore has not been initialized");
+        }
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        ensureInitialized();
+        synchronized (state.lock) {
+            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(ruleDetailsFileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        String violationsText = readStoreFile(ruleDetailsFileName);
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(String fileName) {
+        ResolvedFile file = resolveFile(fileName);
+        if (file.broken) {
+            throw new StoreReadException(new IOException("Violation file is not a regular file directly in the store folder: " + fileName));
+        }
+        try {
+            String result = new String(toByteArray(file.lexicalPath.toFile()), UTF_8);
+            return ensureUnixLineBreaks(result);
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    private String fileNameOrThrow(String description, Class<? extends RuntimeException> exceptionType) {
+        String fileName;
+        try {
+            fileName = ruleViolationFileNameStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            throw e;
+        }
+        if (fileName == null || fileName.trim().isEmpty()) {
+            String message = String.format("RuleViolationFileNameStrategy yielded no name for rule '%s'", description);
+            if (exceptionType == StoreInitializationFailedException.class) {
+                throw new StoreInitializationFailedException(message);
+            }
+            throw new StoreUpdateFailedException(message);
+        }
+        return fileName;
+    }
+
+    private IntegrityReport analyze(FileSyncedProperties properties, StoreContext storeContext,
+            RuleViolationFileNameStrategy strategy) {
+        List<IntegrityEntry> entries = new ArrayList<>();
+        for (String propertyName : properties.stringPropertyNames()) {
+            String description = ensureUnixLineBreaks(propertyName);
+            String fileName = properties.getProperty(description);
+            String derivedName = deriveForInitialization(description, strategy);
+            ResolvedFile resolvedFile = resolveFile(fileName, storeContext);
+            boolean broken = resolvedFile.broken || resolvedFile.actualPath.equals(storeContext.indexRealPath);
+            boolean resolved = !broken && hasNoViolations(resolvedFile.lexicalPath);
+            entries.add(new IntegrityEntry(description, fileName, derivedName, resolvedFile, broken, resolved));
+        }
+
+        markShared(entries);
+        markColliding(entries);
+        for (IntegrityEntry entry : entries) {
+            entry.misplaced = !entry.fileName.equals(entry.derivedName);
+            if (entry.misplaced) {
+                Path derivedPath = storeContext.folderPath.resolve(entry.derivedName).normalize();
+                entry.occupied = !isDirectPath(derivedPath, storeContext.folderPath)
+                        || isPathOutsideFolder(derivedPath, storeContext)
+                        || Files.exists(derivedPath, LinkOption.NOFOLLOW_LINKS)
+                        || isRecordedByAnotherEntry(entry, entries);
+            }
+        }
+        return new IntegrityReport(entries, findUnownedFiles(storeContext.folderPath, storeContext.indexPath));
