    private IntegrityMode parseIntegrity(Properties properties) {
        String value = properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT);
        if (INTEGRITY_REPAIR.equals(value)) {
            return IntegrityMode.REPAIR;
        }
        if (INTEGRITY_FAIL.equals(value)) {
